1	// contract.mjs — the piece contract, read in one place. A piece says in its own
2	// <head> what it needs from its host; a gathered proof nobody should edit has a
3	// `contract` block in its manifest entry instead; Loudon's grants live in
4	// grants.json. From those three this module works out how the piece is framed,
5	// what its chips say, and the policies the piece origin sends with it. The page
6	// (rich-handler.mjs → _api/resolve), STIGMERGY's deck (GET /api/piece), the
7	// piece origin (piece-origin.mjs) and the public build all ask here, so a piece
8	// is framed the same way wherever it is shown. Plan: STIGMERGY — spec —
9	// rich-face pieces § 3.
10	//
11	//   <meta name="piece:needs" content="camera storage">     camera microphone midi storage fullscreen
12	//   <meta name="piece:files" content="frames.json data/">  beside the piece, or /palace/absolute; a
13	//                                                          folder ends in "/"; a space in a name is %20
14	//   <meta name="piece:net"   content="storage.googleapis.com">
15	//   <meta name="piece:size"  content="fill 4/3">           flow (the default: the piece reports its
16	//                                                          height) or fill <w>/<h> (sized from the column)
17	//
18	// Lists split on spaces and commas. Camera, microphone, midi and every net host
19	// also need a line in grants.json, written only on Loudon's yes; that file is
20	// the real gate, sent as each piece's Permissions-Policy.
21	
22	import { readFileSync, statSync } from 'node:fs';
23	import { join, posix } from 'node:path';
24	
25	export const NEEDS = ['camera', 'microphone', 'midi', 'storage', 'fullscreen'];
26	// Needs that also take a grant line (so does every net host).
27	export const GRANTED_NEEDS = ['camera', 'microphone', 'midi'];
28	// A frame's height: what it takes from a piece, and what it shows until told.
29	export const CAPS = { min: 120, max: 8000, fallback: 800 };
30	export const GRANTS_FILE = '_ops/rich-face/grants.json';
31	export const SHELF_FILE = '_ops/rich-face/libs.json';
32	// Served on the piece origin to every piece: Flocking's pieces load palace-tokens.js from here.
33	export const DESIGN_SYSTEM = '_ops/loudon-live/design-system/';
34	// …all but the review layer, whose notes land in storage a face does not keep (review-layer.js:96-97).
35	export const REVIEW_LAYER = '_ops/loudon-live/design-system/ui_kits/review-layer/';
36	// The CDNs pieces load libraries from today, until libs.json (the shelf) names its own.
37	const DEFAULT_SHELF = ['https://unpkg.com', 'https://cdn.jsdelivr.net', 'https://cdnjs.cloudflare.com'];
38	
39	const words = (v) => (Array.isArray(v) ? v.map(String) : String(v ?? '').split(/[\s,]+/)).map((s) => s.trim()).filter(Boolean);
40	const safeDecode = (s) => { try { return decodeURIComponent(s); } catch { return s; } };
41	
42	// Every <meta> in the page's head, as { name, content }.
43	function metas(html) {
44	  const s = String(html || '');
45	  const end = s.search(/<\/head\s*>|<body[\s>]/i);
46	  const head = s.slice(0, end < 0 ? 64 * 1024 : end);
47	  const out = [];
48	  for (const m of head.matchAll(/<meta\b([^>]*)>/gi)) {
49	    const attrs = {};
50	    for (const a of m[1].matchAll(/([\w:-]+)\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'>]+))/g)) attrs[a[1].toLowerCase()] = a[2] ?? a[3] ?? a[4] ?? '';
51	    if (attrs.name) out.push({ name: attrs.name.toLowerCase(), content: attrs.content ?? '' });
52	  }
53	  return out;
54	}
55	
56	function parseSize(v, problems) {
57	  const t = String(v ?? '').trim().toLowerCase();
58	  if (!t || t === 'flow') return { mode: 'flow' };
59	  const m = t.match(/^fill\s+(\d+(?:\.\d+)?)(?:\s*\/\s*(\d+(?:\.\d+)?))?$/);
60	  if (m) {
61	    const ratio = m[2] ? Number(m[1]) / Number(m[2]) : Number(m[1]);
62	    if (ratio > 0.1 && ratio < 10) return { mode: 'fill', ratio, as: m[2] ? `${m[1]}/${m[2]}` : m[1] };
63	  }
64	  problems.push(`size “${v}” is not flow or fill <w>/<h>`);
65	  return { mode: 'flow' };
66	}
67	
68	const hostOf = (v) => { const t = String(v).trim().toLowerCase(); try { return new URL(t.includes('://') ? t : `https://${t}`).host; } catch { return null; } };
69	
70	/** One declaration from its parts (a piece's metas, or a manifest's contract block). */
71	function declaration(parts) {
72	  const problems = [];
73	  const needs = [];
74	  for (const n of words(parts.needs).map((x) => x.toLowerCase())) {
75	    if (!NEEDS.includes(n)) problems.push(`“${n}” is not a need (${NEEDS.join(', ')})`);
76	    else if (!needs.includes(n)) needs.push(n);
77	  }
78	  const files = [...new Set(words(parts.files).map(safeDecode))];
79	  const net = [];
80	  for (const h of words(parts.net)) { const host = hostOf(h); if (!host) problems.push(`net “${h}” is not a host`); else if (!net.includes(host)) net.push(host); }
81	  return { needs, files, net, size: parseSize(parts.size, problems), problems };
82	}
83	
84	/**
85	 * What a piece declares in its own <head>, or null when it declares nothing.
86	 * @returns {null | { needs: string[], files: string[], net: string[], size: object, problems: string[] }}
87	 */
88	export function readDeclaration(html) {
89	  const parts = {};
90	  let any = false;
91	  for (const { name, content } of metas(html)) {
92	    const key = name.startsWith('piece:') ? name.slice(6) : null;
93	    if (!key) continue;
94	    any = true;
95	    if (['needs', 'files', 'net', 'size'].includes(key)) parts[key] = parts[key] ? `${parts[key]} ${content}` : content;
96	  }
97	  return any ? declaration(parts) : null;
98	}
99	
100	/**
101	 * The contract a piece is held to: its own declaration, or else its manifest
102	 * entry's `contract` block (the manifest speaks for a gathered proof), or else
103	 * none — a pre-contract piece, framed as every piece was before the contract.
104	 */
105	export function contractOf({ html, manifestContract } = {}) {
106	  const own = readDeclaration(html);
107	  if (own) return { source: 'piece', ...own };
108	  if (manifestContract && typeof manifestContract === 'object') return { source: 'manifest', ...declaration(manifestContract) };
109	  return { source: null, needs: [], files: [], net: [], size: { mode: 'flow' }, problems: [] };
110	}
111	
112	/**
113	 * A declared file as a palace path, named from the piece at `piecePath`.
114	 * A folder keeps its trailing "/". Null for one that climbs out of the palace.
115	 */
116	export function declaredPath(piecePath, ref) {
117	  const r = String(ref || '').trim();
118	  if (!r) return null;
119	  const dir = r.endsWith('/');
120	  const joined = r.startsWith('/') ? r.replace(/^\/+/, '') : posix.join(posix.dirname(piecePath), r);
121	  const p = posix.normalize(joined).replace(/\/+$/, '');
122	  if (!p || p === '.' || p === '..' || p.startsWith('../')) return null;
123	  return dir ? `${p}/` : p;
124	}
125	
126	// ── grants.json ────────────────────────────────────────────────────────────
127	// { "grants": [ { "piece": "<palace path>", "allow": ["camera"], "net": ["host"], "yes": "Loudon, <date>" } ] }
128	const grantCache = new Map(); // root -> { mtimeMs, value }
129	
130	/** The grants Loudon has given: piece path → { allow: Set, net: Set }. A file that is missing grants nothing. */
131	export function readGrants(root) {
132	  const file = join(root, ...GRANTS_FILE.split('/'));
133	  let st;
134	  try { st = statSync(file); } catch { return { ok: true, byPiece: new Map(), error: null }; }
135	  const hit = grantCache.get(root);
136	  if (hit && hit.mtimeMs === st.mtimeMs) return hit.value;
137	  let value;
138	  try {
139	    const json = JSON.parse(readFileSync(file, 'utf8'));
140	    const byPiece = new Map();
141	    for (const g of Array.isArray(json.grants) ? json.grants : []) {
142	      if (!g || typeof g.piece !== 'string') continue;
143	      const cur = byPiece.get(g.piece) || { allow: new Set(), net: new Set() };
144	      for (const a of words(g.allow).map((x) => x.toLowerCase())) if (GRANTED_NEEDS.includes(a)) cur.allow.add(a);
145	      for (const h of words(g.net)) { const host = hostOf(h); if (host) cur.net.add(host); }
146	      byPiece.set(g.piece, cur);
147	    }
148	    value = { ok: true, byPiece, error: null };
149	  } catch (e) {
150	    value = { ok: false, byPiece: new Map(), error: `${GRANTS_FILE} could not be read, so nothing is granted: ${e.message}` };
151	  }
152	  grantCache.set(root, { mtimeMs: st.mtimeMs, value });
153	  return value;
154	}
155	
156	// ── the shelf ──────────────────────────────────────────────────────────────
157	/** The origins a piece may load libraries from: every https URL libs.json names, or today's three CDNs. */
158	export function shelfOrigins(root) {
159	  let json;
160	  try { json = JSON.parse(readFileSync(join(root, ...SHELF_FILE.split('/')), 'utf8')); } catch { return DEFAULT_SHELF; }
161	  const found = new Set();
162	  (function walk(v) {
163	    if (Array.isArray(v)) v.forEach(walk);
164	    else if (v && typeof v === 'object') Object.values(v).forEach(walk);
165	    else if (typeof v === 'string' && /^https:\/\//i.test(v)) { try { found.add(new URL(v).origin); } catch { /* not a url */ } }
166	  })(json);
167	  return found.size ? [...found].sort() : DEFAULT_SHELF;
168	}
169	
170	// ── the frame ──────────────────────────────────────────────────────────────
171	const LABEL = { camera: 'camera', microphone: 'microphone', midi: 'midi' };
172	
173	/**
174	 * How a piece is framed and what its figure says. The same plan feeds the rich
175	 * page and STIGMERGY's deck; each only renders it.
176	 * @param {object} o
177	 * @param {string} o.path           the piece's palace path
178	 * @param {object} o.contract       from contractOf
179	 * @param {{ allow: Set, net: Set } | undefined} o.grant  its line in grants.json
180	 * @param {'live'|'static'} [o.mode] live: on the piece origin; static: the public read view, opaque
181	 * @param {string} [o.origin]       the piece origin, live
182	 * @param {string} [o.url]          where the piece is fetched, static
183	 */
184	export function framePlan({ path, contract, grant, mode = 'live', origin, url }) {
185	  const c = contract || contractOf();
186	  const g = grant || { allow: new Set(), net: new Set() };
187	  const chips = [];
188	  const allow = ['autoplay'];
189	  const refused = [];
190	  const isStatic = mode === 'static';
191	  for (const need of c.needs) {
192	    if (GRANTED_NEEDS.includes(need)) {
193	      if (isStatic) { chips.push({ text: `${LABEL[need]} · opens in its own tab`, state: 'note', title: 'On the public site a camera or microphone piece runs in its own tab, not in the face.' }); continue; }
194	      if (g.allow.has(need)) { allow.push(need); chips.push({ text: LABEL[need], state: 'ok', title: `granted in ${GRANTS_FILE}` }); }
195	      else { refused.push(need); chips.push({ text: `${LABEL[need]} · not granted`, state: 'warn', title: `declared, but ${GRANTS_FILE} has no line for this piece, so the browser refuses it` }); }
196	    } else if (need === 'storage') {
197	      chips.push(isStatic
198	        ? { text: 'storage · this visit only', state: 'note', title: 'The public site keeps a piece’s storage in memory: it is gone when the page closes.' }
199	        : { text: 'storage', state: 'ok', title: 'kept on the piece origin, under this piece’s own prefix' });
200	    } else if (need === 'fullscreen') {
201	      allow.push('fullscreen');
202	      chips.push({ text: 'fullscreen', state: 'ok', title: 'may go fullscreen' });
203	    }
204	  }
205	  if (c.files.length) chips.push({ text: `files · ${c.files.length}`, state: 'ok', title: `declared files: ${c.files.join(', ')}` });
206	  const net = [];
207	  for (const host of c.net) {
208	    if (isStatic || g.net.has(host)) { net.push(host); chips.push({ text: `net · ${host}`, state: 'ok', title: isStatic ? 'reaches this host' : `granted in ${GRANTS_FILE}` }); }
209	    else { refused.push(`net ${host}`); chips.push({ text: `net · ${host} · not granted`, state: 'warn', title: `declared, but ${GRANTS_FILE} has no line for it, so the piece cannot reach it` }); }
210	  }
211	  if (c.size.mode === 'fill') chips.push({ text: `fill ${c.size.as}`, state: 'ok', title: 'sized from the column' });
212	  if (c.problems.length) chips.push({ text: `declaration · ${c.problems.length} problem${c.problems.length === 1 ? '' : 's'}`, state: 'warn', title: c.problems.join('; ') });
213	  if (c.source === 'manifest') chips.push({ text: 'declared by its manifest', state: 'note', title: 'a gathered proof: its manifest entry speaks for it' });
214	  // A piece that needs anything of its origin — a device, storage, a file
215	  // beside it — runs as the piece origin; the page adds allow-same-origin only
216	  // after checking that origin is not its own. Everything else stays opaque.
217	  const sameOrigin = !isStatic && (c.needs.some((n) => n !== 'fullscreen') || c.files.length > 0);
218	  return {
219	    path,
220	    url: isStatic ? url : `${origin}/${String(path).split('/').map(encodeURIComponent).join('/')}`,
221	    mark: c.source ? 'introduced' : 'pre-contract',
222	    source: c.source,
223	    needs: c.needs, files: c.files, net, size: c.size, problems: c.problems,
224	    sameOrigin,
225	    allow: [...new Set(allow)].join('; '),
226	    refused,
227	    tab: isStatic && c.needs.some((n) => n === 'camera' || n === 'microphone'),
228	    chips,
229	  };
230	}
231	
232	/** The Permissions-Policy the piece origin sends with a piece: what grants.json allows it, and nothing else. */
233	export function piecePolicy(plan) {
234	  const on = (need) => (plan && plan.allow.split('; ').includes(need) ? 'self' : '');
235	  return [
236	    `camera=(${on('camera')})`, `microphone=(${on('microphone')})`, `midi=(${on('midi')})`, `fullscreen=(${on('fullscreen')})`,
237	    'geolocation=()', 'display-capture=()', 'usb=()', 'serial=()', 'hid=()', 'bluetooth=()', 'payment=()',
238	  ].join(', ');
239	}
240	
241	/**
242	 * The piece's Content-Security-Policy: where its data may go. Scripts from the
243	 * shelf; fetches to the piece origin and the hosts it was granted. It limits
244	 * where data goes, not what code runs; the shelf's SRI pins are the defense
245	 * for that (spec § 7). It ships report-only for one round.
246	 */
247	export function pieceCsp(plan, shelf = DEFAULT_SHELF) {
248	  const s = shelf.join(' ');
249	  const net = (plan ? plan.net : []).map((h) => `https://${h}`).join(' ');
250	  return [
251	    "default-src 'self'",
252	    `script-src 'self' 'unsafe-inline' 'unsafe-eval' 'wasm-unsafe-eval' blob: ${s}`,
253	    `style-src 'self' 'unsafe-inline' https://fonts.googleapis.com ${s}`,
254	    `font-src 'self' data: https://fonts.gstatic.com ${s}`,
255	    "img-src 'self' data: blob:",
256	    "media-src 'self' data: blob: mediastream:",
257	    `connect-src 'self' ${net}`.trim(),
258	    "worker-src 'self' blob:",
259	    "frame-src 'none'", "object-src 'none'", "base-uri 'self'", "form-action 'none'",
260	  ].join('; ');
261	}
